function historyHtml(){return `<h3>Your recent account races</h3>${history.length?history.map(h=>`<p>${esc(h.date)} · ${esc(RALLY_MODES[h.mode]?.label||'Circuit Cup')}${h.questionMode==='adaptive'?' · Adaptive':''} · ${esc(h.topic)} · ${esc(h.correct)}/${esc(h.answered)} correct · ${h.finished?'Position '+esc(h.position):'Race ended'}</p>`).join(''):'<p>Complete your first race to set a personal best.</p>'}`}
