function importLegacyProgress(){const owner=rallyProgress.getOwner();if(!owner||!hasLegacyProgress())return;if(!window.confirm('Import the older Rally stars, courses and races saved on this device into your signed-in account? Only continue if that progress belongs to you.'))return;try{const read=(key,fallback)=>JSON.parse(localStorage.getItem(key)||'null')||fallback;const patch={cup:read('mezzo_rally_cup_v1',{}),progress:read('mezzo_rally_live_progress_v1',{}),garage:read('mezzo_rally_garage_v1',{}),history:read('mezzo_rally_history_v1',[]).slice(0,10).map((r,i)=>({...r,id:crypto.randomUUID(),completedAt:new Date(Date.now()-i).toISOString()}))};rallyProgress.update(patch);localStorage.setItem('mezzo_rally_legacy_claimed_v1',owner);refreshAccountProgress()}catch{const slot=overlay?.querySelector('[data-rally-account-sync]');if(slot)slot.textContent='The older device progress could not be read. Your account progress is unchanged.'}}
