let adaptivePractice=null
let classRace=null
let overlay=null,questionPool=[],questions=[],race=null,index=0,questionSince=0,locked=false,paused=false,stage='setup',raf=0,last=0,holdUntil=0,sound=false,audio=null,loadVersion=0,demo=false,history=[],previousFocus=null,oldOverflow=''
function readHistory(){return rallyProgress.getState().history}
function shell(body){renderer3D?.dispose();renderer3D=null;overlay.scrollTop=0;overlay.innerHTML=`<div class="rally-shell"><header class="rally-header"><div class="rally-brand">MEZZO <b>MATHS RALLY</b></div><div><button class="rally-button" data-rally-sound aria-pressed="${sound}">${sound?'Sound on':'Sound off'}</button> <button class="rally-button" data-rally-close>Exit game ✕</button></div></header><div data-rally-account-sync>${syncPanel()}</div><div data-rally-content>${body}</div></div>`}
async function openGame(assigned=null){if(overlay)throw Error('Finish or exit the current race first.');classRace=assigned?{...assigned,previousConfig:lastConfig,previousTrack:selectedTrackId}:null;previousFocus=document.activeElement;oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';overlay=document.createElement('section');overlay.className='rally-overlay';overlay.setAttribute('role','dialog');overlay.setAttribute('aria-modal','true');overlay.setAttribute('aria-label','Mezzo Maths Rally');document.body.append(overlay);const current=overlay;if(classRace){const a=classRace.assignment;await startRace(false,{class_level:a.class_level,curriculum:a.curriculum,topic:a.topic,rally_course:a.rally.track,difficulty:a.rally.pace,race_view:'2d'});overlay?.querySelector('[data-rally-close]')?.focus();return}shell('<p class="rally-copy">Loading your Rally progress…</p>');try{const session=await supabase?.auth.getSession();if(overlay!==current)return;rallyProgress.setOwner(session?.data?.session?.user?.id||null);await rallyProgress.sync()}catch{}if(overlay!==current)return;applyAccountProgress();showSetup();overlay.querySelector('[data-rally-close]').focus()}

function closeGame(){adaptivePractice=null;if(classRace){lastConfig=classRace.previousConfig;selectedTrackId=classRace.previousTrack;classRace=null}renderer3D?.dispose();renderer3D=null;loadVersion++;cancelAnimationFrame(raf);overlay?.remove();overlay=null;race=null;stage='setup';document.body.style.overflow=oldOverflow;previousFocus?.focus?.()}
function adventurePanel(){const earned=cupStars(cup);return `<section class="rally-adventure-panel" data-rally-adventure><div class="rally-course-heading"><div><span class="rally-kicker">YOUR GHANA RACING ADVENTURE</span><h2>Choose a world. Make the car yours.</h2></div><strong class="rally-star-wallet">★ ${earned} / ${RALLY_TRACKS.length*3} course stars</strong></div><div class="rally-worlds">${RALLY_WORLDS.map(world=>`<button type="button" data-rally-world="${world.id}" class="rally-world ${garage.world===world.id?'selected':''}" aria-pressed="${garage.world===world.id}" style="--world-land:${world.land};--world-dark:${world.dark}"><span>${world.icon}</span><strong>${esc(world.name)}</strong><small>${esc(world.description)}</small></button>`).join('')}</div><div class="rally-garage-heading"><h3>Your garage</h3><p>Earn stars by finishing and answering accurately. Car upgrades are cosmetic.</p></div><div class="rally-garage">${RALLY_CARS.map((car,i)=>`<button type="button" data-rally-car="${car.id}" class="rally-garage-car ${garage.car===car.id?'selected':''}" aria-pressed="${garage.car===car.id}" ${earned<car.stars?'disabled':''}><svg viewBox="0 0 140 64" aria-hidden="true"><ellipse cx="70" cy="43" rx="59" ry="10" fill="#050e1a"/><path d="M12 33 24 24 45 23 58 12 88 12 104 24 124 28 130 39 123 45 17 45Z" fill="${colourFor(garage.colour).hex}"/><path d="M51 23 62 15 84 15 96 24Z" fill="#1b3f56"/><path d="M73 15v9" stroke="#c9f7ff"/><circle cx="39" cy="44" r="11" fill="#101927"/><circle cx="39" cy="44" r="5" fill="#8aabbc"/><circle cx="106" cy="44" r="11" fill="#101927"/><circle cx="106" cy="44" r="5" fill="#8aabbc"/>${car.id==='monster'?'<rect x="30" y="16" width="65" height="24" rx="4" fill="#43c9ff"/><rect x="67" y="18" width="23" height="15" fill="#173449"/><circle cx="39" cy="44" r="15" fill="#0c1521"/><circle cx="106" cy="44" r="15" fill="#0c1521"/><circle cx="39" cy="44" r="7" fill="#9baebb"/><circle cx="106" cy="44" r="7" fill="#9baebb"/>':''}${i>1?'<path d="M15 19h22v5H15Z" fill="#acbbc8"/>':''}${i===3?'<path d="M20 28h95" stroke="#f4d356" stroke-width="3"/>':''}</svg><strong>${esc(car.name)}</strong><small>${earned>=car.stars?garage.car===car.id?'SELECTED':'UNLOCKED':`🔒 Earn ${car.stars} stars`}</small><span>${esc(car.description)}</span></button>`).join('')}</div><div class="rally-paint-row"><strong>Paint</strong>${RALLY_COLOURS.map(colour=>`<button type="button" data-rally-colour="${colour.id}" class="rally-paint ${garage.colour===colour.id?'selected':''}" style="--paint:${colour.hex}" aria-label="${colour.name}${earned<colour.stars?' · unlock at '+colour.stars+' stars':''}" aria-pressed="${garage.colour===colour.id}" ${earned<colour.stars?'disabled':''}><i></i><span>${esc(colour.name)}${earned<colour.stars?' 🔒':''}</span></button>`).join('')}</div><p class="rally-copy" style="font-size:12px">Garage choices and earned stars are linked to your signed-in account.</p></section>`}
function chooseGarage(key,value){if(!rallyProgress.getOwner())return;garage=garagePrefs({...garage,[key]:value},cup);rallyProgress.update({garage});drawTrack(0)}
function readCup(){return rallyProgress.getState().cup}

function courseOptions(){return RALLY_TRACKS.map((track,i)=>`<option value="${track.id}" ${track.id===selectedTrackId?'selected':''}>${i+1}. ${esc(track.name)}</option>`).join('')}
function courseCards(config=currentConfig()){const quick=quickRace(config);return `<section class="rally-course-picker"><div class="rally-course-heading"><div><span class="rally-kicker">${quick?'QUICK PRACTICE':'THE MEZZO CIRCUIT CUP'}</span><h2>${RALLY_TRACKS.length} courses. Find your racing line.</h2></div><p>${quick?'Short practice on any course. Quick races are recorded in your history. Choose Circuit Cup to earn course stars and unlock stages.':'Start with Stage 1. Complete every question to unlock the next stage for your chosen class and topic.<br>Finish: ★ · 60% accuracy: ★★ · Win with 80% accuracy: ★★★'}</p></div><div class="rally-course-grid">${RALLY_TRACKS.map((track,i)=>{const stars=Math.max(0,Math.min(3,Number(cup[track.id])||0));return `<button type="button" class="rally-course-card ${selectedTrackId===track.id?'selected':''}" data-rally-course="${track.id}" aria-pressed="${selectedTrackId===track.id}"><span>LEVEL ${i+1} · ${esc(track.shape)}</span><svg viewBox="0 0 100 100" aria-hidden="true"><polyline points="${track.points.filter((_,j)=>j%Math.max(1,Math.floor(track.points.length/80))===0||j===track.points.length-1).map(p=>p.x*100+','+p.y*100).join(' ')}" fill="none" stroke="currentColor" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/></svg><strong>${esc(track.name)}</strong><small>${racePlan(track.id,config).questions} questions · ${esc(track.description)}</small>${quick?'<b>Quick practice</b>':`<b aria-label="${stars} of 3 stars">${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</b>`}</button>`}).join('')}</div></section>`}
function selectCourse(id){if(!canPlayStage(id,currentConfig()))return;selectedTrackId=getTrack(id).id;const select=overlay?.querySelector('[name="rally_course"]');if(select)select.value=selectedTrackId;overlay?.querySelectorAll('[data-rally-course]').forEach(button=>{const active=button.dataset.rallyCourse===selectedTrackId;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active))});drawTrack(0);updateAvailability()}
function showSetup(){cancelAnimationFrame(raf);race=null;stage='setup';shell(`<section class="rally-hero"><div><span class="rally-kicker">THE FINISH LINE IS EARNED</span><h1>Think fast.<br>Drive <em>faster.</em></h1><p class="rally-copy">Your answers power your car. Race Kofi, Ama and Kojo in a quick practice race or the Circuit Cup. Build a streak, earn turbo and take the chequered flag.</p><div class="rally-pills"><span>3 computer opponents</span><span>Answer-powered racing</span><span>Touch & keyboard</span></div><canvas class="rally-canvas" width="900" height="400" data-rally-canvas aria-label="Preview of a four-car race track"></canvas></div><form class="rally-setup" data-rally-setup><h2>Build your race</h2><div class="rally-fields"><label>Race length<select name="race_mode"><option value="quick5" selected>Quick race · 5 questions · 600 m</option><option value="quick10">Quick race · 10 questions · 900 m</option><option value="cup">Circuit Cup · 5–55 questions · 1,200 m</option></select></label><label>Question selection<select name="question_mode"><option value="adaptive" selected>Adaptive practice</option><option value="balanced">Balanced mix</option></select></label><label>Class<select name="class_level">${choices(LEVELS,'Grade 4')}</select></label><label>Curriculum<select name="curriculum">${choices(CURRICULA,'GES')}</select></label><label>Topic<select name="topic"><option>Loading topics…</option></select></label><label>Course<select name="rally_course">${courseOptions()}</select></label><label>Race view<select name="race_view"><option value="2d">2D · all courses</option><option value="3d">3D · Monster Stadium</option></select></label><label>Opponent pace<select name="difficulty"><option value="rookie">Rookie · gentler pace</option><option value="club" selected>Club · balanced race</option><option value="expert">Expert · fast opponents</option></select></label></div><p class="rally-status" role="status" data-rally-status>Loading the question bank…</p><button type="submit" class="rally-button primary" data-rally-start disabled>START YOUR ENGINES →</button><div class="rally-actions"><button type="button" class="rally-button" data-rally-reload-bank>Reload question bank</button></div><p class="rally-copy" style="font-size:12px">Correct answers earn acceleration. Quick answers add a bonus. Four correct answers charge turbo. Switch tabs to pause. Quick races have 5 or 10 questions and shorter distances. Adaptive practice adjusts the next question after your answers; Balanced mix keeps a varied set. Adaptive selection applies to quick races. Circuit Cup starts at 5 questions and adds 5 per stage, with stars and course unlocks. Answer every question before crossing the finish line. Race practice stays separate from official BECE results.</p></form></section>${adventurePanel()}${courseCards({race_mode:lastConfig?.race_mode||'quick5'})}<section class="rally-history" data-rally-history>${historyHtml()}</section>`);const setup=overlay.querySelector('[data-rally-setup]');if(lastConfig){for(const key of ['class_level','curriculum','difficulty','race_view','race_mode','question_mode'])if(setup.elements[key])setup.elements[key].value=lastConfig[key]??(key==='race_mode'?'cup':setup.elements[key].value)}syncQuestionMode();drawTrack(0);loadQuestions()}
function validQuestion(q){return q.id&&q.question_text&&/^[ABCD]$/.test(q.correct_answer)&&['a','b','c','d'].every(k=>q['option_'+k]||q['option_'+k+'_image_url'])}
async function bankRequest(params){const query=params?'?'+new URLSearchParams(params):'';const session=await supabase?.auth.getSession();const token=session?.data?.session?.access_token;const response=await fetch('/api/rally-questions'+query,{headers:token?{Authorization:'Bearer '+token}:{},signal:AbortSignal.timeout(25000)});const body=await response.json();if(!response.ok)throw Error(body.error||'Question bank unavailable. Please retry.');return body.data||[]}
async function loadQuestions(){const version=++loadVersion,form=overlay?.querySelector('[data-rally-setup]');if(!form)return;form.querySelector('[data-rally-start]').disabled=true;form.querySelector('[data-rally-status]').textContent='Loading question-bank topics…';questionPool=[];try{const rows=await bankRequest();if(version!==loadVersion||!form.isConnected)return;const topics=orderGrade4Topics(form.elements.class_level.value,form.elements.curriculum.value,[...new Set(rows.filter(r=>r.class_level===form.elements.class_level.value&&r.curriculum===form.elements.curriculum.value).map(r=>r.topic).filter(t=>typeof t==='string'&&t.trim()))].sort());const selected=topics.includes(lastConfig?.topic)?lastConfig.topic:ALL_TOPICS;form.elements.topic.innerHTML=`<option value="${ALL_TOPICS}" ${selected===ALL_TOPICS?'selected':''}>All topics (including unassigned)</option>`+(form.elements.class_level.value==='Grade 4'&&form.elements.curriculum.value==='GES'?grade4TopicOptions(topics,selected):choices(topics,selected));await loadTopicQuestions()}catch(error){if(version===loadVersion&&form.isConnected){form.elements.topic.innerHTML='<option>Unavailable</option>';form.querySelector('[data-rally-status]').innerHTML=esc(error.message)+(/sign.in/i.test(error.message)?' <button type="button" class="rally-button primary" data-rally-sign-in>Sign in / Join</button>':'')}}}
async function loadTopicQuestions(){const version=++loadVersion,form=overlay?.querySelector('[data-rally-setup]');if(!form)return;questionPool=[];form.querySelector('[data-rally-start]').disabled=true;form.querySelector('[data-rally-status]').textContent='Loading actual race questions…';try{const rows=await bankRequest({class_level:form.elements.class_level.value,curriculum:form.elements.curriculum.value,...(form.elements.topic.value===ALL_TOPICS?{}:{topic:form.elements.topic.value})});if(version!==loadVersion||!form.isConnected)return;questionPool=[...new Map(rows.filter(validQuestion).map(q=>[q.question_text.trim(),q])).values()];updateAvailability()}catch(error){if(version===loadVersion&&form.isConnected)form.querySelector('[data-rally-status]').innerHTML=esc(error.message)+(/sign.in/i.test(error.message)?' <button type="button" class="rally-button primary" data-rally-sign-in>Sign in / Join</button>':'')}}
function updateAvailability(){const form=overlay?.querySelector('[data-rally-setup]');if(!form)return;const track=form.elements.rally_course.value,required=racePlan(track,currentConfig()).questions,count=questionPool.filter(q=>matchesTopic(q,form.elements.topic.value)).length;const config=Object.fromEntries(new FormData(form)),unlocked=canPlayStage(track,config);for(const button of overlay.querySelectorAll('[data-rally-course]')){button.disabled=!canPlayStage(button.dataset.rallyCourse,config)}for(const option of form.elements.rally_course.options){option.disabled=!canPlayStage(option.value,config)}form.querySelector('[data-rally-start]').disabled=count<required||!unlocked;form.querySelector('[data-rally-status]').textContent=!unlocked?'Complete all questions in the preceding stage for this class and topic to unlock this course.':count>=required?`${getTrack(track).name}: ${required} questions · ${racePlan(track,config).distance.toLocaleString()} m · ${count} available. ${quickRace(config)?'Quick practice; no Cup stars or stage unlocks.':'Answer every question to progress through the Cup.'}`:`${getTrack(track).name} needs ${required} questions; ${count} available for this selection. Choose another topic or upload questions for this class and curriculum.`}
async function startRace(isDemo=false,continued=null){const form=overlay?.querySelector('[data-rally-setup]');const config=continued||Object.fromEntries(new FormData(form));demo=false;selectedTrackId=config.rally_course;if(!classRace&&!canPlayStage(selectedTrackId,config)){showSetup();return}const required=classRace?classRace.questions.length:racePlan(selectedTrackId,config).questions;const pool=classRace?classRace.questions:questionPool.filter(q=>matchesTopic(q,config.topic));adaptivePractice=!classRace&&quickRace(config)&&config.question_mode==='adaptive'?createAdaptivePractice(pool):null;questions=classRace?[...pool]:selectVariedQuestions(pool,required);if(adaptivePractice)placeAdaptiveQuestion(questions,0,nextAdaptiveQuestion(adaptivePractice));if(questions.length!==required){showSetup();const status=overlay.querySelector('[data-rally-status]');if(status)status.textContent=`This stage requires ${required} questions. Choose a topic with enough bank questions.`;return;}lastConfig={...config};loadVersion++;selectedTrackId=config.rally_course;race=createRace(config.difficulty,required);const plan=classRace?{mode:'class',quick:false,distance:1200}:racePlan(selectedTrackId,config);race.mode=plan.mode;race.quick=plan.quick;race.finishDistance=plan.distance;if(classRace)race.maxSeconds=Number(classRace.assignment.duration_minutes)*60;race.stageTrackId=selectedTrackId;race.trackId=config.race_view==='3d'?'monster':selectedTrackId;race.view=config.race_view||'2d';race.world=garage.world;race.car=garage.car;race.colour=garage.colour;if(race.trackId==='monster'){race.world='monster';race.car='monster'}race.classLevel=config.class_level;race.curriculum=config.curriculum;race.topic=config.topic===ALL_TOPICS?'All topics':config.topic;index=0;if(classRace){for(const q of questions)if(Object.hasOwn(classRace.answers,q.position))answerRace(race,q,classRace.answers[q.position],0);while(index<questions.length&&race.answers.some(a=>a.id===questions[index].id))index++}questionSince=0;locked=false;paused=false;stage='countdown';holdUntil=3;last=0;shell(`<div data-rally-pause-slot></div><div class="rally-race-layout"><div class="rally-track-pane"><div class="rally-race-title"><div><span class="rally-kicker">${race.quick?'MEZZO QUICK RACE':'MEZZO CIRCUIT CUP'}</span><h2>${classRace?'Class race':race.quick?'Quick race':'Stage '+(RALLY_TRACKS.findIndex(t=>t.id===race.stageTrackId)+1)} · ${race.view==='3d'?'3D Monster Stadium':esc(getTrack(race.trackId).name)}</h2></div><span>${esc(worldFor(race.world).name)}</span></div><div class="rally-hud"><article><small>Position</small><strong data-rally-position>4 / 4</strong></article><article><small>Speed</small><strong data-rally-speed>0</strong></article><article><small>Distance</small><strong data-rally-distance>0 m</strong></article><article><small>Accuracy</small><strong data-rally-accuracy>—</strong></article></div><canvas class="rally-canvas" width="1000" height="650" data-rally-canvas aria-label="Animated race track with your selected car and three computer opponents"></canvas><div class="rally-3d-controls" data-rally-3d-controls>${race.view==='3d'?'<button class="rally-button" data-rally-camera>Camera: stadium · switch to chase</button><strong data-rally-countdown></strong>':''}</div><div class="rally-standings" data-rally-standings aria-label="Live race order"></div></div><div class="rally-bottom"><section class="rally-question" data-rally-question aria-label="Race question"></section><aside class="rally-side"><span class="rally-kicker">YOUR TURBO</span><div class="rally-meter" style="margin-top:12px"><i data-rally-turbo-meter style="width:0%"></i></div><button class="rally-button primary rally-turbo" data-rally-turbo disabled>TURBO · charging</button><p data-rally-streak>0 correct in a row</p><p>Keys <b>1–4</b> answer. <b>Space</b> activates turbo. Accuracy earns the main boost.</p><button class="rally-button" data-rally-pause>Pause race</button>${demo?'<p class="rally-demo">Demo race · arithmetic practice</p>':''}<p>${esc(race.classLevel)} · ${esc(race.curriculum)}<br>${esc(race.topic)}</p></aside></div></div>`);renderQuestion();if(race.view==='3d'){const current=race;try{const {createStadium3D}=await import('./maths-rally-3d.js');if(!overlay||race!==current)return;renderer3D=createStadium3D(overlay.querySelector('[data-rally-canvas]'))}catch(error){if(!overlay||race!==current)return;stage='graphics-error';overlay.querySelector('[data-rally-3d-controls]').innerHTML=`<p role="alert">${esc(error.message||'3D could not load on this device.')}</p><button class="rally-button primary" data-rally-2d-fallback>Continue in 2D</button><button class="rally-button" data-rally-again>Change details</button>`;return}}raf=requestAnimationFrame(frame)}
function renderQuestion(){const box=overlay?.querySelector('[data-rally-question]');if(!box)return;if(index>=questions.length){box.innerHTML='<small>ALL QUESTIONS ANSWERED</small><h2>Final sprint!</h2><p>Your accuracy sets your cruising speed. Use any charged turbo and race to the flag.</p>';return}const q=questions[index];if(classRace&&stage==='race'&&classRace.activeId!==q.id){classRace.activeId=q.id;classRace.onQuestion(q)}box.innerHTML=`<small>${classRace?'CLASS RACE':race.quick?'QUICK RACE':'STAGE '+(RALLY_TRACKS.findIndex(t=>t.id===race.stageTrackId)+1)} · QUESTION ${index+1} / ${questions.length} · <span data-rally-question-clock>0s</span></small><h2>${renderVectorText(q.question_text)}</h2>${adaptivePractice?`<p class="rally-adaptive-note"><b>Adaptive practice · ${esc(adaptiveQuestionLabel(adaptivePractice,q))}</b><br>${esc(adaptivePractice.message)}</p>`:''}${q.question_image_url?`<img src="${esc(q.question_image_url)}" alt="Question diagram">`:''}<div class="rally-answer-grid">${['a','b','c','d'].map((k,i)=>`<button type="button" class="rally-answer" data-rally-answer="${'ABCD'[i]}" ${stage==='countdown'?'disabled':''}><b>${i+1}</b><span>${renderVectorText(q['option_'+k]||'')}${q['option_'+k+'_image_url']?`<img src="${esc(q['option_'+k+'_image_url'])}" alt="Option ${'ABCD'[i]} diagram">`:''}</span></button>`).join('')}</div><div class="rally-feedback" role="status" data-rally-feedback></div>`}
function beep(correct=true){if(!sound)return;try{audio||=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.connect(gain);gain.connect(audio.destination);oscillator.frequency.setValueAtTime(correct?740:190,audio.currentTime);gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);oscillator.start();oscillator.stop(audio.currentTime+.16)}catch{}}
function chooseAnswer(selected){if(stage!=='race'||paused||locked||index>=questions.length)return;if(classRace&&Date.now()>=classRace.deadline){finishAssignedRace();return}if(classRace&&classRace.remaining(questions[index])===0)selected='';locked=true;const result=answerRace(race,questions[index],selected,race.elapsed-questionSince);if(!result)return;if(classRace)classRace.onAnswer(questions[index],selected);if(adaptivePractice){recordAdaptiveAnswer(adaptivePractice,questions[index],result.correct);if(index+1<questions.length)placeAdaptiveQuestion(questions,index+1,nextAdaptiveQuestion(adaptivePractice))}beep(result.correct);const feedback=overlay.querySelector('[data-rally-feedback]');feedback.textContent=result.correct?'Correct! Acceleration earned.':`Correct answer: ${result.correct_answer}. ${result.explanation||'Review this question after the race.'}`;overlay.querySelectorAll('[data-rally-answer]').forEach(button=>{button.disabled=true;button.classList.toggle('right',button.dataset.rallyAnswer===result.correct_answer);button.classList.toggle('wrong',button.dataset.rallyAnswer===selected&&!result.correct)});holdUntil=race.elapsed+(result.correct?.85:2.8)}
function togglePause(force){if(!race||race.finished)return;paused=typeof force==='boolean'?force:!paused;const slot=overlay.querySelector('[data-rally-pause-slot]');slot.innerHTML=paused?`<div class="rally-paused"><strong>${classRace?'Cars paused. Your class and question timers continue.':'Race paused — cars and clocks are stopped.'}</strong> <button class="rally-button primary" data-rally-resume>Resume race</button></div>`:'';last=0;overlay.querySelector('[data-rally-pause]').textContent=paused?'Resume race':'Pause race';overlay.querySelectorAll('[data-rally-answer]').forEach(b=>b.disabled=paused||locked||stage==='countdown')}
function frame(time){if(!overlay||!race||stage==='results')return;if(classRace&&Date.now()>=classRace.deadline){finishAssignedRace();return}if(classRace&&stage==='race'&&!locked&&index<questions.length&&classRace.remaining(questions[index])===0){const wasPaused=paused;paused=false;chooseAnswer('');paused=wasPaused;}if(!race||!overlay)return;const dt=last?Math.max(0,Math.min(5,(time-last)/1000)):0;last=time;if(!paused){if(stage==='countdown'){holdUntil-=dt;if(holdUntil<=0){stage='race';holdUntil=0;renderQuestion();beep()}}else{for(let remaining=dt;remaining>0&&!race.finished;remaining-=.05)tickRace(race,Math.min(.05,remaining),index>=questions.length);if(locked&&race.elapsed>=holdUntil){index++;locked=false;questionSince=race.elapsed;renderQuestion()}if(race.finished){showResults();return}}}drawTrack(time/1000);if(time-hudTime>100){updateHud();hudTime=time}raf=requestAnimationFrame(frame)}
